import{_ as d,c as a,o as r,ah as e}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"陰陽と八卦","description":"陰陽と八卦，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"陰陽と八卦","description":"陰陽と八卦，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/yinyang/index.md","filePath":"ja/articles/yinyang/index.md"}'),l={name:"ja/articles/yinyang/index.md"};function i(h,t,n,o,s,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="易経における太極と陰陽-概念・数の対応・応用" tabindex="-1">易経における太極と陰陽：概念・数の対応・応用 <a class="header-anchor" href="#易経における太極と陰陽-概念・数の対応・応用" aria-label="Permalink to “易経における太極と陰陽：概念・数の対応・応用”">​</a></h1><h2 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to “核心”">​</a></h2><p>陰陽は「対立しながら一つである」「動的にバランスする」「互いに転じ合う」ことを示します。陰の中に陽があり、陽の中に陰があります。</p><h2 id="身近な例" tabindex="-1">身近な例 <a class="header-anchor" href="#身近な例" aria-label="Permalink to “身近な例”">​</a></h2><ul><li>時間：昼夜、四季の移り変わり。</li><li>からだ：寒熱、虚実、臓腑の陰陽。</li><li>思考：二項対立に偏らず、状況のバランスと転換点を見る。</li></ul><p>易経では、<strong>太極</strong>を宇宙の根源、<strong>陰陽</strong>を生成変化の基礎として捉え、そこに「数（数理）」と「関係の法則」を重ねて、自然と人事を読む枠組みを作ります。</p><h3 id="_1-太極-根源としての「一」" tabindex="-1">1. 太極：根源としての「一」 <a class="header-anchor" href="#_1-太極-根源としての「一」" aria-label="Permalink to “1. 太極：根源としての「一」”">​</a></h3><p>『繋辞上』に「易に太極あり、是れ両儀を生ず」とあるように、太極は分化以前の総体で、数の「一」に対応します。ここでの「一」は単なる数量ではなく、<strong>絶対的な統一（可能性の総体）</strong>を意味します。「一」が分かれて陰陽（両儀）が生じ、変化が始まります。</p><h3 id="_2-陰陽-属性と数の対応" tabindex="-1">2. 陰陽：属性と数の対応 <a class="header-anchor" href="#_2-陰陽-属性と数の対応" aria-label="Permalink to “2. 陰陽：属性と数の対応”">​</a></h3><p>陰陽は数の「二」に対応し、宇宙の基本規則としての二分を表します。</p><ul><li><strong>陽</strong>：能動・明・剛健・上昇 → 奇数（1/3/5/7/9）に対応。</li><li><strong>陰</strong>：受動・暗・柔順・下降 → 偶数（2/4/6/8/10）に対応。</li></ul><p>陰陽の展開は、四象（老陽・少陽・老陰・少陰）→ 八卦（乾・坤・震・巽・坎・離・艮・兌）へと進みます。乾は純陽、坤は純陰で、他の卦は陰陽が混在し、バランスと動きを表現します。</p><h3 id="_3-太極と陰陽の三つの関係-実践の要点" tabindex="-1">3. 太極と陰陽の三つの関係（実践の要点） <a class="header-anchor" href="#_3-太極と陰陽の三つの関係-実践の要点" aria-label="Permalink to “3. 太極と陰陽の三つの関係（実践の要点）”">​</a></h3><ol><li><p><strong>対立統一</strong>：陰陽は反対でありながら、太極（統一）に根ざして相互依存します。</p><ul><li>例：心（陽）と腎（陰）のように、片方だけでは成り立たない。</li></ul></li><li><p><strong>消長平衡</strong>：陰陽は量的に増減し、全体の均衡を保とうとします。</p><ul><li>例：春に陽が伸び、夏に陽が極まり、秋に陰が生じ、冬に陰が極まる。</li></ul></li><li><p><strong>動静転化</strong>：極まれば転じる。動と静は固定ではなく、循環の中で入れ替わります。</p><ul><li>例：昼から夜へ、夜から昼へ。占筮では動爻が「転換点」を示します。</li></ul></li></ol><h3 id="_4-影響-易の読み方の土台" tabindex="-1">4. 影響：易の読み方の土台 <a class="header-anchor" href="#_4-影響-易の読み方の土台" aria-label="Permalink to “4. 影響：易の読み方の土台”">​</a></h3><p>太極と陰陽の考え方は、「天人合一」の世界観として、哲学・生活技術（住まい、養生）・倫理（剛柔の調和）へ広く浸透しました。占いとしてだけでなく、<strong>変化を見るための思考法</strong>として読むのが要点です。</p><hr><h1 id="八卦の属性と応用" tabindex="-1">八卦の属性と応用 <a class="header-anchor" href="#八卦の属性と応用" aria-label="Permalink to “八卦の属性と応用”">​</a></h1><h2 id="_1-八卦の概要" tabindex="-1">1. 八卦の概要 <a class="header-anchor" href="#_1-八卦の概要" aria-label="Permalink to “1. 八卦の概要”">​</a></h2><p>八卦は伏羲に由来するとされる象徴体系で、陰爻（--）と陽爻（—）を三本一組にして、乾・坤・震・巽・坎・離・艮・兌を作ります。要点は「象で理を喩える」こと――卦象の意味を通して、自然・人事・心身の関係を読む枠組みです。</p><h2 id="_2-多次元の対応-基本" tabindex="-1">2. 多次元の対応（基本） <a class="header-anchor" href="#_2-多次元の対応-基本" aria-label="Permalink to “2. 多次元の対応（基本）”">​</a></h2><p>八卦は単なる記号ではなく、方位・季節・家族役割・臓腑などと対応づけられてきました。これは「天人合一」の発想の具体化であり、占筮や養生、空間設計などの基礎になります。</p><h3 id="_2-1-方位-後天八卦の目安" tabindex="-1">2.1 方位（後天八卦の目安） <a class="header-anchor" href="#_2-1-方位-後天八卦の目安" aria-label="Permalink to “2.1 方位（後天八卦の目安）”">​</a></h3><ul><li>乾：西北（天門）</li><li>坤：西南（地戸）</li><li>震：東（春の始動）</li><li>巽：東南（伸展・浸透）</li><li>坎：北（冬の蔵）</li><li>離：南（夏の盛）</li><li>艮：東北（止・転換）</li><li>兌：西（収斂・悦）</li></ul><p>※ 風水的な応用では、方位の性質を「開放」「安定」「生気」「静止」などの環境要素に読み替えて用います。</p><h3 id="_2-2-季節-イメージ" tabindex="-1">2.2 季節（イメージ） <a class="header-anchor" href="#_2-2-季節-イメージ" aria-label="Permalink to “2.2 季節（イメージ）”">​</a></h3><ul><li>震：春（生・起動）</li><li>巽：春末（伸び・伝播）</li><li>離：夏（明・熱）</li><li>兌：秋（収・悦）</li><li>坎：冬（蔵・養）</li><li>艮：冬末〜春（止・転じ）</li><li>乾／坤：季節の端境（変わり目）として語られることがあります</li></ul><h3 id="_2-3-家族役割・心身の対応-代表例" tabindex="-1">2.3 家族役割・心身の対応（代表例） <a class="header-anchor" href="#_2-3-家族役割・心身の対応-代表例" aria-label="Permalink to “2.3 家族役割・心身の対応（代表例）”">​</a></h3><table tabindex="0"><thead><tr><th>卦</th><th>家族役割</th><th>からだ（例）</th><th>心の象意（例）</th></tr></thead><tbody><tr><td>乾</td><td>父</td><td>頭・肺</td><td>意志・威厳</td></tr><tr><td>坤</td><td>母</td><td>腹・脾</td><td>包容・忍耐</td></tr><tr><td>震</td><td>長男</td><td>足・肝</td><td>行動・衝動</td></tr><tr><td>巽</td><td>長女</td><td>大腿・胆</td><td>柔軟・伝達</td></tr><tr><td>坎</td><td>中男</td><td>耳・腎</td><td>恐れ・慎重</td></tr><tr><td>離</td><td>中女</td><td>目・心</td><td>喜び・明晰</td></tr><tr><td>艮</td><td>少男</td><td>手・胃</td><td>止・節度</td></tr><tr><td>兌</td><td>少女</td><td>口・肺</td><td>言葉・悦</td></tr></tbody></table><p>（注）対応関係は流派によって差があり、固定の断定ではなく「読みの補助輪」として扱うのが安全です。</p><h2 id="_3-応用の方向性-学習用" tabindex="-1">3. 応用の方向性（学習用） <a class="header-anchor" href="#_3-応用の方向性-学習用" aria-label="Permalink to “3. 応用の方向性（学習用）”">​</a></h2><h3 id="_3-1-空間-住まい・作業環境" tabindex="-1">3.1 空間（住まい・作業環境） <a class="header-anchor" href="#_3-1-空間-住まい・作業環境" aria-label="Permalink to “3.1 空間（住まい・作業環境）”">​</a></h3><p>方位と象意を手がかりに、「休む」「集まる」「動く」「話す」などの用途と整合するように考えます（例：休息＝坎の静、対話＝兌の言）。</p><h3 id="_3-2-養生-バランス" tabindex="-1">3.2 養生（バランス） <a class="header-anchor" href="#_3-2-養生-バランス" aria-label="Permalink to “3.2 養生（バランス）”">​</a></h3><p>季節と五行を手がかりに、過不足を整える発想を学びます（例：暑い時期は冷ます、寒い時期は温める）。</p><h3 id="_3-3-占筮-判断の補助" tabindex="-1">3.3 占筮（判断の補助） <a class="header-anchor" href="#_3-3-占筮-判断の補助" aria-label="Permalink to “3.3 占筮（判断の補助）”">​</a></h3><p>卦を「象で理を喩える」ものとして読み、現状（体）と傾向（用）、動爻（転換点）を整理して、具体的な行動に落とし込みます。</p><h2 id="_4-まとめ" tabindex="-1">4. まとめ <a class="header-anchor" href="#_4-まとめ" aria-label="Permalink to “4. まとめ”">​</a></h2><p>八卦は、自然・人事・心身を一つの言語で扱うための「対応表」のような役割を持ちます。方位や季節、役割の象意を押さえると、卦の読みが立体的になり、学習や内省に役立ちます。</p><hr><h1 id="八卦-基本八卦-の詳解" tabindex="-1">八卦（基本八卦）の詳解 <a class="header-anchor" href="#八卦-基本八卦-の詳解" aria-label="Permalink to “八卦（基本八卦）の詳解”">​</a></h1><p>八卦は『易経』の中核となる記号体系です。「—」（陽爻：剛健・能動）と「--」（陰爻：柔順・受動）を、三本一組で組み合わせて八つの基本卦を作り、天地の主要な自然イメージに対応させます。八卦は六十四卦を構成する最小単位でもあります。</p><h2 id="_1-基本八卦の早見表" tabindex="-1">1. 基本八卦の早見表 <a class="header-anchor" href="#_1-基本八卦の早見表" aria-label="Permalink to “1. 基本八卦の早見表”">​</a></h2><p>（注）二進数は「下から上へ」数え、陽＝1、陰＝0。先天方位＝伏羲先天、後天方位＝文王後天。</p><table tabindex="0"><thead><tr><th>卦名</th><th>記号</th><th>先天数</th><th>五行</th><th>基本イメージ（例）</th><th>先天方位</th><th>後天方位</th></tr></thead><tbody><tr><td>乾</td><td>☰</td><td>1</td><td>金</td><td>天・父・君・剛健・円</td><td>南</td><td>西北</td></tr><tr><td>坤</td><td>☷</td><td>8</td><td>土</td><td>地・母・受容・方</td><td>北</td><td>西南</td></tr><tr><td>震</td><td>☳</td><td>4</td><td>木</td><td>雷・長男・動・覚醒</td><td>東北</td><td>東</td></tr><tr><td>巽</td><td>☴</td><td>5</td><td>木</td><td>風・長女・入・浸透</td><td>西南</td><td>東南</td></tr><tr><td>坎</td><td>☵</td><td>6</td><td>水</td><td>水・中男・険・智</td><td>西</td><td>北</td></tr><tr><td>離</td><td>☲</td><td>3</td><td>火</td><td>火・中女・明・麗</td><td>東</td><td>南</td></tr><tr><td>艮</td><td>☶</td><td>7</td><td>土</td><td>山・少男・止・安定</td><td>西北</td><td>東北</td></tr><tr><td>兌</td><td>☱</td><td>2</td><td>金</td><td>沢・少女・悦・言</td><td>東南</td><td>西</td></tr></tbody></table><h2 id="_2-八卦から六十四卦へ-復卦の形成" tabindex="-1">2. 八卦から六十四卦へ（復卦の形成） <a class="header-anchor" href="#_2-八卦から六十四卦へ-復卦の形成" aria-label="Permalink to “2. 八卦から六十四卦へ（復卦の形成）”">​</a></h2><p>八卦（三爻卦＝経卦）を上下に重ねて六爻卦（六十四卦）を作ります。</p><ul><li>下：内卦（下卦）＝初爻〜三爻</li><li>上：外卦（上卦）＝四爻〜六爻</li></ul><p>一般に「外卦のイメージ＋内卦のイメージ」で呼びます（例：水雷屯、山水蒙）。</p><table tabindex="0"><thead><tr><th>卦名</th><th>記号</th><th>内卦（下）＋外卦（上）</th><th>概要</th></tr></thead><tbody><tr><td>乾為天</td><td>䷀</td><td>乾＋乾</td><td>剛健不息、伸びる力</td></tr><tr><td>坤為地</td><td>䷁</td><td>坤＋坤</td><td>受容と涵養、厚徳</td></tr><tr><td>水雷屯</td><td>䷂</td><td>震＋坎</td><td>始まりの難、準備と積み上げ</td></tr><tr><td>山水蒙</td><td>䷃</td><td>坎＋艮</td><td>未熟の学び、啓蒙</td></tr></tbody></table><p>数学的にも、8 卦×8 卦で 64 通りの組合せが得られます。</p><h2 id="_3-八卦のイメージと文字文化-例" tabindex="-1">3. 八卦のイメージと文字文化（例） <a class="header-anchor" href="#_3-八卦のイメージと文字文化-例" aria-label="Permalink to “3. 八卦のイメージと文字文化（例）”">​</a></h2><p>八卦は自然現象を象徴化した体系であり、「天・地・雷・風・水・火・山・沢」といった語やイメージは、日常言語の中にも深く入り込んでいます。卦の象意を押さえると、古典表現や比喩の読み取りがしやすくなります。</p>',53)])])}const _=d(l,[["render",i]]);export{b as __pageData,_ as default};
